blocks.body:
Tool: get_context_overview
Description: Get the compact overview for the current insight target. Use this first when you need high-level context before deciding on narrower retrieval.
Parameters:
{
  "type": "object",
  "properties": {
    "max_chars": {
      "type": "integer",
      "description": "Maximum number of characters in the returned payload. Default: 1200."
    }
  }
}

Tool: get_latest_session
Description: Get the latest completed session details for the current exercise. Prefer this before broader history when diagnosing current performance.
Parameters:
{
  "type": "object",
  "properties": {
    "max_chars": {
      "type": "integer",
      "description": "Maximum number of characters in the returned payload. Default: 1400."
    }
  }
}

Tool: get_recent_sessions
Description: Get the most recent completed sessions for the current exercise. Use this when you need short-term trend context after checking the latest session.
Parameters:
{
  "type": "object",
  "properties": {
    "limit": {
      "type": "integer",
      "description": "How many recent sessions to return. Default: 3."
    },
    "max_chars": {
      "type": "integer",
      "description": "Maximum number of characters in the returned payload. Default: 2200."
    }
  }
}

Tool: summarize_older_history
Description: Return a compact summary of older exercise history while keeping the newest sessions separate. Use only when recent sessions are not enough.
Parameters:
{
  "type": "object",
  "properties": {
    "keep_recent": {
      "type": "integer",
      "description": "How many most recent sessions to exclude from the summary. Default: 2."
    },
    "max_chars": {
      "type": "integer",
      "description": "Maximum number of characters in the returned summary. Default: 1400."
    }
  }
}

Tool: get_full_compact_history
Description: Get the full compacted exercise history when a broader view is required and the smaller tools are still insufficient.
Parameters:
{
  "type": "object",
  "properties": {
    "max_chars": {
      "type": "integer",
      "description": "Maximum number of characters in the returned payload. Default: 3000."
    }
  }
}

Tool: get_context_overview
Payload:
{"ok":true,"target":"Probe Squat","overview":"# Probe Squat history"}
